import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
  // ============ REFS ============
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const detectionIntervalRef = useRef(null);
  const detectionTimeoutRef = useRef(null);
  const progressIntervalRef = useRef(null);

  // ============ STATE ============
  const [cameraActive, setCameraActive] = useState(false);
  const [detecting, setDetecting] = useState(false);
  const [detectionProgress, setDetectionProgress] = useState(0);
  const [enrollmentPhoto, setEnrollmentPhoto] = useState(null);
  const [capturedPhoto, setCapturedPhoto] = useState(null);
  const [matchResult, setMatchResult] = useState(null);
  const [error, setError] = useState(null);
  const [cameraPermission, setCameraPermission] = useState(null);
  const [videoReady, setVideoReady] = useState(false);

  // ============ VÉRIFIER PERMISSIONS CAMÉRA ============
  useEffect(() => {
    const checkCameraPermission = async () => {
      try {
        const result = await navigator.permissions.query({ name: 'camera' });
        setCameraPermission(result.state);

        result.addEventListener('change', () => {
          setCameraPermission(result.state);
        });
      } catch (err) {
        console.warn('⚠️ Permissions API non disponible:', err);
      }
    };

    checkCameraPermission();
  }, []);

  // ============ DÉMARRAGE CAMÉRA (CORRIGÉ) ============
  const startCamera = async () => {
    try {
      console.log('🎥 Démarrage caméra...');
      setError(null);

      // Arrêter la caméra précédente si elle existe
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
        streamRef.current = null;
      }

      // Demander accès à la caméra avec contraintes optimisées
      const constraints = {
        video: {
          facingMode: 'user',
          width: { ideal: 1280, min: 640 },
          height: { ideal: 720, min: 480 },
          aspectRatio: { ideal: 1.77 }
        },
        audio: false
      };

      console.log('📋 Demande accès caméra avec contraintes:', constraints);

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      console.log('✅ Stream obtenu:', stream);

      streamRef.current = stream;
      setCameraActive(true);

      // Écouter l'événement loadedmetadata pour s'assurer que la vidéo est prête
      const handleVideoReady = () => {
        console.log('✅ Vidéo prête à jouer');
        console.log('📹 Résolution:', {
          width: videoRef.current.videoWidth,
          height: videoRef.current.videoHeight
        });
        setVideoReady(true);
        setCameraActive(true);
        if (addNotification) addNotification('✅ Caméra activée', 'success');
      };

      if (videoRef.current.readyState >= 2) {
        // Si déjà prêt
        handleVideoReady();
      } else {
        // Sinon attendre
        videoRef.current.addEventListener('loadedmetadata', handleVideoReady, { once: true });
      }

      // Fallback: activer la caméra après 1 seconde de toute façon
      setTimeout(() => {
        if (videoRef.current && videoRef.current.srcObject) {
          setCameraActive(true);
          setVideoReady(true);
        }
      }, 1000);

    } catch (err) {
      console.error('❌ Erreur caméra complète:', err);
      console.error('Nom erreur:', err.name);
      console.error('Message:', err.message);

      let errMsg = 'Impossible d\'accéder à la caméra';

      if (err.name === 'NotAllowedError') {
        errMsg = 'Permission caméra refusée. Vérifiez les paramètres de sécurité';
      } else if (err.name === 'NotFoundError') {
        errMsg = 'Aucune caméra détectée sur cet appareil';
      } else if (err.name === 'NotReadableError') {
        errMsg = 'La caméra est utilisée par une autre application';
      } else if (err.name === 'OverconstrainedError') {
        errMsg = 'Les contraintes caméra ne peuvent pas être satisfaites';
      }

      setError(errMsg);
      if (addNotification) addNotification(`❌ ${errMsg}`, 'error');
    }
  };

  // ============ ARRÊTER CAMÉRA ============
  const stopCamera = () => {
    console.log('🛑 Arrêt caméra...');

    // Nettoyer les intervals
    if (detectionIntervalRef.current) {
      clearInterval(detectionIntervalRef.current);
      detectionIntervalRef.current = null;
    }

    if (detectionTimeoutRef.current) {
      clearTimeout(detectionTimeoutRef.current);
      detectionTimeoutRef.current = null;
    }

    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }

    // Arrêter tous les tracks
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        console.log('🛑 Arrêt track:', track.kind);
        track.stop();
      });
      streamRef.current = null;
    }

    // Vider la source vidéo
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }

    setCameraActive(false);
    setDetecting(false);
    setDetectionProgress(0);
    setVideoReady(false);
    console.log('✅ Caméra arrêtée');
  };

  // ============ NETTOYAGE À LA FERMETURE ============
  useEffect(() => {
    return () => {
      console.log('🧹 Nettoyage composant');
      stopCamera();
    };
  }, []);
  useEffect(() => {
    if (cameraActive && videoRef.current && streamRef.current) {
      console.log('🔗 Liaison vidéo + stream');
      videoRef.current.srcObject = streamRef.current;
    }
    }, [cameraActive]);
  // ============ FILTRE ANTI-FLOU ============
  const isBlurry = (canvas) => {
    const ctx = canvas.getContext('2d');
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

    let sum = 0;
    for (let i = 0; i < imageData.data.length; i += 4) {
      sum += imageData.data[i];
    }

    const avg = sum / (imageData.data.length / 4);
    return avg < 60; // seuil ajustable
  };
    // ============ LANCER DÉTECTION 10 SECONDES ============
  const startDetection = async () => {
    if (!videoRef.current) {
      setError('Erreur: vidéo non disponible');
      return;
    }

    if (!cameraActive) {
      setError('Veuillez d\'abord activer la caméra');
      return;
    }

    console.log('▶️ Lancement détection 10 secondes...');
    setDetecting(true);
    setDetectionProgress(0);
    setMatchResult(null);
    setError(null);

    let candidates = [];
    let startTime = Date.now();
    const DETECTION_DURATION = 10000; // 10 secondes
    let frameCount = 0;

    // Fonction pour capturer et envoyer frame
    const captureFrame = async () => {
      try {
        if (!videoRef.current || !videoRef.current.srcObject) {
          console.warn('⚠️ Stream non disponible');
          return;
        }

        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;

        if (canvas.width === 0 || canvas.height === 0) {
          console.warn('⚠️ Dimensions vidéo invalides');
          return;
        }

        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        // ❌ ignorer image floue
        if (isBlurry(canvas)) {
          console.log('⚠️ Image floue ignorée');
          return;
        }

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.9);
        frameCount++;
        console.log(`📸 Frame ${frameCount} capturé (${canvas.width}x${canvas.height})`);

        // Envoyer au backend
        try {
          const response = await attendanceAPI.recognize(imageBase64);
          const data = response?.data;

          console.log('📥 Réponse:', data);

          if (data && data.success && data.student) {
            candidates.push({
              ...data,
              photo: imageBase64
            });

            console.log(`✅ candidat ajouté: ${data.student} (${(data.confidence * 100).toFixed(1)}%)`);
          }
        } catch (apiErr) {
          console.warn('⚠️ Erreur API:', apiErr.message);
        }
      } catch (err) {
        console.warn('⚠️ Erreur capture frame:', err.message);
      }
    };

    // Boucle de capture toutes les 500ms
    detectionIntervalRef.current = setInterval(captureFrame, 300);

    // Arrêt automatique après 10 secondes
    detectionTimeoutRef.current = setTimeout(() => {
      if (detectionIntervalRef.current) {
        clearInterval(detectionIntervalRef.current);
        detectionIntervalRef.current = null;
      }

      console.log(`⏹️ Détection terminée (${frameCount} frames capturés)`);
      setDetecting(false);
      setDetectionProgress(100);

      // Afficher le résultat

      if (candidates.length > 0) {
        const best = candidates.sort((a, b) => b.confidence - a.confidence)[0];

        if (best.confidence > 0.5) {
          handleDetectionSuccess(best);
        } else {
          setError('⚠️ Confiance insuffisante');
        }
      } else {
        const msg = '❌ Aucun visage reconnu pendant les 10 secondes';
        setError(msg);
        if (addNotification) addNotification('⚠️ Aucune détection', 'error');
      }
    }, DETECTION_DURATION);

    // Mettre à jour la barre de progression
    progressIntervalRef.current = setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(100, (elapsed / DETECTION_DURATION) * 100);
      setDetectionProgress(progress);

      if (progress >= 100) {
        clearInterval(progressIntervalRef.current);
        progressIntervalRef.current = null;
      }
    }, 100);
  };

  // ============ CAPTURER UNE FOIS ============
  const captureOnce = async () => {
    if (!videoRef.current) {
      setError('Erreur: vidéo non disponible');
      return;
    }

    if (!cameraActive) {
      setError('Veuillez d\'abord activer la caméra');
      return;
    }

    console.log('📸 Capture unique...');
    setError(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;

      if (canvas.width === 0 || canvas.height === 0) {
        setError('❌ Résolution vidéo invalide');
        return;
      }

      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.92);

      console.log('📤 Envoi de la capture au serveur...');

      const response = await attendanceAPI.recognize(imageBase64);
      const data = response?.data;

      console.log('📥 Réponse serveur:', data);

      if (data && data.success && data.student) {
        handleDetectionSuccess({ ...data, photo: imageBase64 });
      } else {
        const msg = data?.message || 'Visage non reconnu';
        setError(`❌ ${msg}`);
        if (addNotification) addNotification('⚠️ Visage non reconnu', 'error');
      }
    } catch (err) {
      const msg = err?.message || 'Erreur serveur';
      console.error('❌ Erreur capture:', err);
      setError(`❌ ${msg}`);
      if (addNotification) addNotification(`❌ ${msg}`, 'error');
    }
  };

  // ============ TRAITER SUCCÈS DÉTECTION ============
  const handleDetectionSuccess = async (matchData) => {
    try {
      console.log('🎉 Traitement détection réussie...');

      // Capturer la photo finale
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);
      const finalPhoto = canvas.toDataURL('image/jpeg', 0.92);

      setCapturedPhoto(finalPhoto);

      setMatchResult({
        success: true,
        name: matchData.student || 'Inconnu',
        email: matchData.email || 'N/A',
        confidence: (matchData.confidence * 100).toFixed(1),
        attendanceId: matchData.attendance_id || 'N/A',
        timestamp: new Date().toLocaleTimeString('fr-FR')
      });

      if (addNotification) {
        addNotification(`✅ ${matchData.student} détecté!`, 'success');
      }

      console.log('✅ Succès détection:', matchData.student);
    } catch (err) {
      console.error('❌ Erreur traitement:', err);
      setError('❌ Erreur traitement résultat');
      if (addNotification) addNotification('❌ Erreur traitement', 'error');
    }
  };

  // ============ NOUVELLE DÉTECTION ============
  const resetDetection = () => {
    setMatchResult(null);
    setEnrollmentPhoto(null);
    setCapturedPhoto(null);
    setDetectionProgress(0);
    setError(null);
    console.log('🔄 Réinitialisation');
  };

  // ============ RENDU ============
  return (
    <div style={styles.container}>
      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.title}>👤 Reconnaissance Faciale</h1>
        <p style={styles.subtitle}>
          {!cameraActive
            ? 'Cliquez sur "Allumer caméra" pour commencer'
            : videoReady
            ? 'Alignez votre visage avec la caméra'
            : 'Initialisation caméra...'}
        </p>
      </div>

      {/* AFFICHAGE ÉTAT PERMISSIONS */}
      {cameraPermission && (
        <div style={{
          ...styles.infoBox,
          backgroundColor: cameraPermission === 'granted' ? '#D1FAE5' : '#FEE2E2',
          borderLeft: `4px solid ${cameraPermission === 'granted' ? COLORS.success : COLORS.danger}`,
          marginBottom: '20px'
        }}>
          <span style={{ 
            color: cameraPermission === 'granted' ? '#065F46' : '#7F1D1D',
            fontWeight: '500'
          }}>
            {cameraPermission === 'granted' 
              ? '✅ Permission caméra accordée' 
              : '⚠️ Permission caméra non accordée'}
          </span>
        </div>
      )}

      {/* CAMÉRA OU MESSAGE */}
      {cameraActive ? (
        <div style={styles.videoSection}>
          <div style={styles.videoContainer}>
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              style={styles.video}
              onLoadedMetadata={() => {
                console.log('✅ Métadonnées vidéo chargées');
                setVideoReady(true);
              }}
            />
            <div style={{
              ...styles.statusBadge,
              background: detecting
                ? 'rgba(79, 70, 229, 0.9)'
                : 'rgba(16, 185, 129, 0.9)'
            }}>
              {detecting ? '🔄 SCANNING...' : '✅ PRÊT'}
            </div>

            {detecting && (
              <div style={styles.timerBadge}>
                ⏱️ {(detectionProgress / 10).toFixed(1)}s / 10s
              </div>
            )}
          </div>

          {/* BARRE DE PROGRESSION */}
          {detecting && (
            <div style={styles.progressBar}>
              <div style={{
                ...styles.progressFill,
                width: `${detectionProgress}%`
              }} />
            </div>
          )}
        </div>
      ) : (
        <div style={styles.cameraOffBox}>
          <p style={styles.cameraOffText}>📹 Caméra désactivée</p>
          <p style={styles.cameraOffSubtext}>Cliquez sur "Allumer caméra" pour démarrer</p>
        </div>
      )}

      {/* BOUTONS D'ACTION */}
      <div style={styles.actions}>
        {!cameraActive ? (
          <button 
            onClick={startCamera} 
            style={{ ...styles.btn, background: COLORS.success }}
          >
            📹 Allumer caméra
          </button>
        ) : (
          <>
            <button
              onClick={captureOnce}
              disabled={detecting || !videoReady}
              style={{
                ...styles.btn,
                background: detecting || !videoReady ? '#94A3B8' : COLORS.primary,
                opacity: detecting || !videoReady ? 0.6 : 1,
                cursor: detecting || !videoReady ? 'not-allowed' : 'pointer'
              }}
            >
              📸 Capturer maintenant
            </button>
            <button
              onClick={startDetection}
              disabled={detecting || !videoReady}
              style={{
                ...styles.btn,
                background: detecting || !videoReady ? '#94A3B8' : COLORS.warning,
                opacity: detecting || !videoReady ? 0.6 : 1,
                cursor: detecting || !videoReady ? 'not-allowed' : 'pointer'
              }}
            >
              🔍 Lancer détection 10s
            </button>
          </>
        )}

        <button
          onClick={stopCamera}
          style={{ ...styles.btn, background: COLORS.danger }}
        >
          🛑 Fermer caméra
        </button>
      </div>

      {/* MESSAGES D'ERREUR */}
      {error && (
        <div style={styles.errorBox}>
          {error}
        </div>
      )}

      {/* RÉSULTAT: 2 IMAGES CÔTE À CÔTE */}
      {matchResult && (
        <div style={styles.resultSection}>
          <h2 style={styles.resultTitle}>✅ {matchResult.name} détecté!</h2>

          <div style={styles.imagesGrid}>
            {/* IMAGE ENRÔLEMENT */}
            <div style={styles.imageColumn}>
              <h3 style={styles.imageTitle}>📸 Photo d'Enrôlement</h3>
              <div style={styles.imagePlaceholder}>
                {enrollmentPhoto ? (
                  <img src={enrollmentPhoto} alt="Enrollment" style={styles.image} />
                ) : (
                  <p style={styles.imagePlaceholderText}>
                    Photo sauvegardée<br />lors de l'inscription
                  </p>
                )}
              </div>
            </div>

            {/* IMAGE CAPTURÉE */}
            <div style={styles.imageColumn}>
              <h3 style={styles.imageTitle}>🎥 Photo Capturée</h3>
              <div style={styles.imagePlaceholder}>
                {capturedPhoto && (
                  <img src={capturedPhoto} alt="Captured" style={styles.image} />
                )}
              </div>
            </div>
          </div>

          {/* INFOS DÉTECTION */}
          <div style={styles.infoBox}>
            <div style={styles.infoRow}>
              <span style={styles.infoLabel}>👤 Nom:</span>
              <span style={styles.infoValue}>{matchResult.name}</span>
            </div>
            <div style={styles.infoRow}>
              <span style={styles.infoLabel}>📧 Email:</span>
              <span style={styles.infoValue}>{matchResult.email}</span>
            </div>
            <div style={styles.infoRow}>
              <span style={styles.infoLabel}>🎯 Confiance:</span>
              <span style={{ ...styles.infoValue, color: COLORS.success, fontWeight: '600' }}>
                {matchResult.confidence}%
              </span>
            </div>
            <div style={styles.infoRow}>
              <span style={styles.infoLabel}>🆔 ID Présence:</span>
              <span style={styles.infoValue}>{matchResult.attendanceId}</span>
            </div>
            <div style={styles.infoRow}>
              <span style={styles.infoLabel}>🕒 Heure:</span>
              <span style={styles.infoValue}>{matchResult.timestamp}</span>
            </div>
          </div>

          {/* BOUTONS APRÈS MATCH */}
          <div style={styles.actionAfterMatch}>
            <button
              onClick={resetDetection}
              style={{ ...styles.btn, background: COLORS.primary }}
            >
              🔄 Nouvelle détection
            </button>
            <button
              onClick={stopCamera}
              style={{ ...styles.btn, background: COLORS.danger }}
            >
              🛑 Fermer caméra
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

